const ASSETS = {"/index.html":{"body":"<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>9月通常授業アンケート</title>\n  <link rel=\"stylesheet\" href=\"./styles.css\">\n</head>\n<body>\n  <main class=\"app\">\n    <header class=\"hero\">\n      <p>進学塾SOIL 出町校</p>\n      <h1>9月通常授業アンケート</h1>\n      <span id=\"pageLead\">来られる曜日・時間を選んで送信してください。</span>\n    </header>\n\n    <nav id=\"tabs\" class=\"tabs\" aria-label=\"入力切り替え\">\n      <a class=\"tab\" data-page-link=\"student\" href=\"./student.html\">生徒用</a>\n      <a class=\"tab\" data-page-link=\"teacher\" href=\"./teacher.html\">講師用</a>\n      <a class=\"tab\" data-page-link=\"admin\" href=\"./admin.html\">管理用</a>\n    </nav>\n\n    <section id=\"studentView\" class=\"panel view\">\n      <div class=\"panel-title\">\n        <h2>生徒用</h2>\n        <p>9月からの通常授業日時を決めるため、最初はすべて〇にしています。来られない日時だけタップして×にしてから提出してください。期限は8/16（日）までです。もし期限内の提出が厳しければお知らせください。</p>\n      </div>\n\n      <form id=\"studentForm\" class=\"form\">\n        <div class=\"student-select-row\">\n          <label>\n            学年\n            <select id=\"studentGrade\" name=\"grade\" required>\n              <option value=\"\">未選択</option>\n            </select>\n          </label>\n\n          <label>\n            生徒名\n            <select id=\"studentName\" name=\"name\" required disabled>\n              <option value=\"\">未選択</option>\n            </select>\n          </label>\n        </div>\n\n        <div class=\"grid-card\">\n          <div class=\"grid-label\">〇＝通塾できる / ×＝通塾できない</div>\n          <div id=\"studentGrid\" class=\"slot-grid student-grid\"></div>\n        </div>\n\n        <div id=\"studentReview\" class=\"own-answer\"></div>\n\n        <label>\n          補足\n          <textarea id=\"studentMemo\" rows=\"3\" placeholder=\"備考欄\"></textarea>\n        </label>\n\n        <button class=\"primary\" type=\"submit\">生徒回答を送信</button>\n      </form>\n    </section>\n\n    <section id=\"teacherView\" class=\"panel view\">\n      <div class=\"panel-title\">\n        <h2>講師用</h2>\n        <p>9月からの勤務日時を決めるため、来れる日時をタップして提出をお願いします。期限は8/16（日）までです。もし期限内の提出が厳しければお知らせください。</p>\n      </div>\n\n      <form id=\"teacherForm\" class=\"form\">\n        <label>\n          講師名\n          <select id=\"teacherName\" name=\"name\" required>\n            <option value=\"\">未選択</option>\n          </select>\n        </label>\n\n        <div class=\"grid-card\">\n          <div class=\"grid-label\">勤務可能な曜日</div>\n          <div id=\"teacherGrid\" class=\"teacher-days\"></div>\n        </div>\n\n        <div id=\"teacherReview\" class=\"own-answer\"></div>\n\n        <label>\n          補足\n          <textarea id=\"teacherMemo\" rows=\"3\" placeholder=\"勤務に関する補足があれば入力してください。\"></textarea>\n        </label>\n\n        <button class=\"primary\" type=\"submit\">講師回答を送信</button>\n      </form>\n    </section>\n\n    <section id=\"adminView\" class=\"panel view\">\n      <div class=\"panel-title\">\n        <h2>管理用</h2>\n        <p>生徒・講師の名前を登録し、回答結果を確認します。</p>\n      </div>\n\n      <div class=\"admin-link-card\">\n        <div>\n          <h3>回答画面</h3>\n          <p>管理画面から、生徒用・講師用の入力画面を確認できます。</p>\n        </div>\n        <div class=\"admin-link-buttons\">\n          <a href=\"./student.html\" target=\"_blank\" rel=\"noopener\">生徒用を開く</a>\n          <a href=\"./teacher.html\" target=\"_blank\" rel=\"noopener\">講師用を開く</a>\n        </div>\n      </div>\n\n      <div class=\"admin-grid\">\n        <section class=\"admin-card\">\n          <h3>生徒名を登録</h3>\n          <form id=\"studentMasterForm\" class=\"master-form\">\n            <input id=\"studentMasterName\" type=\"text\" placeholder=\"生徒名\">\n            <select id=\"studentMasterGrade\">\n              <option value=\"\">学年</option>\n              <option>小4</option>\n              <option>小5</option>\n              <option>小6</option>\n              <option>中1</option>\n              <option>中2</option>\n              <option>中3</option>\n              <option>高1</option>\n              <option>高2</option>\n              <option>高3</option>\n            </select>\n            <button type=\"submit\">追加</button>\n          </form>\n          <div id=\"studentMasterList\" class=\"master-list\"></div>\n        </section>\n\n        <section class=\"admin-card\">\n          <h3>講師名を登録</h3>\n          <form id=\"teacherMasterForm\" class=\"master-form\">\n            <input id=\"teacherMasterName\" type=\"text\" placeholder=\"講師名\">\n            <button type=\"submit\">追加</button>\n          </form>\n          <div id=\"teacherMasterList\" class=\"master-list\"></div>\n        </section>\n      </div>\n\n      <div class=\"admin-actions\">\n        <button id=\"loadResultsButton\" type=\"button\">結果を再読み込み</button>\n        <button id=\"downloadCsvButton\" type=\"button\">CSVを保存</button>\n      </div>\n\n      <div class=\"results-summary\">\n        <span id=\"studentCount\">生徒 0件</span>\n        <span id=\"teacherCount\">講師 0件</span>\n      </div>\n\n      <div id=\"resultsArea\" class=\"results-area\">\n        <p class=\"empty\">まだ読み込んでいません。</p>\n      </div>\n    </section>\n\n    <p id=\"statusMessage\" class=\"status\" aria-live=\"polite\"></p>\n  </main>\n\n  <script src=\"./app.js\"></script>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/student.html":{"body":"<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>生徒用 | 9月通常授業アンケート</title>\n  <script>location.replace(\"./index.html?page=student\");</script>\n</head>\n<body>\n  <a href=\"./index.html?page=student\">生徒用アンケートを開く</a>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/teacher.html":{"body":"<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>講師用 | 9月通常授業アンケート</title>\n  <script>location.replace(\"./index.html?page=teacher\");</script>\n</head>\n<body>\n  <a href=\"./index.html?page=teacher\">講師用アンケートを開く</a>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/admin.html":{"body":"<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>管理用 | 9月通常授業アンケート</title>\n  <script>location.replace(\"./index.html?page=admin\");</script>\n</head>\n<body>\n  <a href=\"./index.html?page=admin\">管理用ページを開く</a>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/styles.css":{"body":":root {\n  --ink: #09224a;\n  --muted: #65758b;\n  --line: #d7e2ef;\n  --panel: #ffffff;\n  --bg: #eef4fb;\n  --blue: #17457f;\n  --blue-soft: #e8f1fb;\n  --green: #0c7a5b;\n  --green-soft: #e8f8f1;\n  --red: #b42318;\n  --shadow: 0 18px 42px rgba(18, 42, 77, 0.12);\n}\n\n* {\n  box-sizing: border-box;\n}\n\nhtml {\n  max-width: 100%;\n  overflow-x: hidden;\n}\n\nbody {\n  margin: 0;\n  color: var(--ink);\n  background: linear-gradient(180deg, #f6f9fd 0%, var(--bg) 100%);\n  font-family: \"Yu Gothic\", \"Yu Gothic UI\", \"Meiryo\", sans-serif;\n  max-width: 100%;\n  overflow-x: hidden;\n}\n\nbutton,\ninput,\nselect,\ntextarea {\n  font: inherit;\n  font-size: 16px;\n}\n\n.app {\n  width: min(1100px, calc(100% - 28px));\n  margin: 0 auto;\n  padding: 22px 0 42px;\n}\n\n.hero {\n  padding: 22px 4px 16px;\n}\n\n.hero p {\n  margin: 0 0 8px;\n  color: var(--blue);\n  font-weight: 700;\n}\n\n.hero h1 {\n  margin: 0;\n  font-size: clamp(28px, 5vw, 42px);\n  letter-spacing: 0;\n}\n\n.hero span {\n  display: block;\n  margin-top: 10px;\n  color: var(--muted);\n  line-height: 1.7;\n}\n\n.tabs {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 8px;\n  position: sticky;\n  top: 0;\n  z-index: 10;\n  padding: 8px 0;\n  background: rgba(246, 249, 253, 0.94);\n  backdrop-filter: blur(8px);\n}\n\nbody[data-page=\"student\"] .tabs,\nbody[data-page=\"teacher\"] .tabs {\n  display: none;\n}\n\n.tab,\n.admin-actions button,\n.primary,\n.master-form button,\n.master-row button {\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #fff;\n  color: var(--ink);\n  min-height: 48px;\n  padding: 10px 14px;\n  font-weight: 700;\n  cursor: pointer;\n  text-align: center;\n  text-decoration: none;\n}\n\n.tab.active,\n.primary,\n.admin-actions button:first-child {\n  background: var(--blue);\n  border-color: var(--blue);\n  color: #fff;\n}\n\n.panel {\n  display: none;\n  margin-top: 14px;\n  padding: 22px;\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  background: var(--panel);\n  box-shadow: var(--shadow);\n}\n\n.panel.active {\n  display: block;\n}\n\n.panel-title {\n  margin-bottom: 18px;\n}\n\n.panel-title h2 {\n  margin: 0 0 6px;\n  font-size: 26px;\n}\n\n.panel-title p {\n  margin: 0;\n  color: var(--muted);\n}\n\n.form {\n  display: grid;\n  gap: 16px;\n}\n\n.student-select-row {\n  display: grid;\n  grid-template-columns: minmax(130px, 180px) minmax(240px, 1fr);\n  gap: 14px;\n  align-items: end;\n}\n\nlabel {\n  display: grid;\n  gap: 8px;\n  font-weight: 700;\n}\n\ninput,\nselect,\ntextarea {\n  width: 100%;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  padding: 12px 14px;\n  background: #fff;\n  color: var(--ink);\n}\n\ninput[readonly] {\n  background: #f6f9fd;\n}\n\ntextarea {\n  resize: vertical;\n}\n\n.grid-card {\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n.grid-label {\n  padding: 12px 14px;\n  background: #f6f9fd;\n  font-weight: 800;\n}\n\n.slot-grid {\n  display: grid;\n  grid-template-columns: 110px repeat(5, 1fr);\n}\n\n.slot-grid > div {\n  min-height: 58px;\n  border: 0;\n  border-top: 1px solid var(--line);\n  border-left: 1px solid var(--line);\n  background: #fff;\n}\n\n.slot-grid > div:nth-child(6n + 1) {\n  border-left: 0;\n}\n\n.head,\n.time {\n  display: grid;\n  place-items: center;\n  background: #f6f9fd !important;\n  font-weight: 800;\n  text-align: center;\n}\n\n.slot {\n  display: grid;\n  place-items: center;\n  min-height: 58px;\n  border: 0;\n  border-top: 1px solid var(--line);\n  border-left: 1px solid var(--line);\n  background: #fff;\n  color: var(--red);\n  font-weight: 800;\n  cursor: pointer;\n}\n\n.slot:focus-visible,\n.teacher-days button:focus-visible {\n  outline: 3px solid rgba(23, 69, 127, 0.22);\n  outline-offset: -3px;\n}\n\n.slot.selected,\n.teacher-days button.selected {\n  background: var(--green-soft);\n  color: var(--green);\n  box-shadow: inset 0 0 0 2px var(--green);\n}\n\n.slot.unavailable {\n  background: #fff7f7;\n  box-shadow: inset 0 0 0 1px #fecaca;\n}\n\n.own-answer {\n  display: none;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  overflow: hidden;\n  background: #fbfdff;\n}\n\n.own-answer:not(:empty) {\n  display: block;\n}\n\n.own-answer-title {\n  padding: 10px 12px;\n  background: #f6f9fd;\n  font-weight: 800;\n}\n\n.own-answer table {\n  width: 100%;\n  border-collapse: collapse;\n}\n\n.own-answer th,\n.own-answer td {\n  padding: 9px 12px;\n  border-top: 1px solid var(--line);\n  text-align: left;\n  vertical-align: top;\n}\n\n.own-answer th {\n  width: 92px;\n  color: var(--muted);\n  font-weight: 800;\n}\n\n.teacher-days {\n  display: grid;\n  grid-template-columns: repeat(6, 1fr);\n}\n\n.teacher-days button {\n  display: grid;\n  gap: 4px;\n  place-items: center;\n  min-height: 58px;\n  border: 0;\n  border-top: 1px solid var(--line);\n  border-left: 1px solid var(--line);\n  background: #fff;\n  padding: 12px 8px;\n  color: var(--muted);\n  font-weight: 800;\n  cursor: pointer;\n}\n\n.teacher-days button strong {\n  min-height: 22px;\n  color: transparent;\n}\n\n.teacher-days button.selected strong {\n  color: var(--green);\n}\n\n.teacher-days button:first-child {\n  border-left: 0;\n}\n\n.teacher-days small {\n  color: inherit;\n  font-size: 12px;\n}\n\n.primary {\n  width: 100%;\n  margin-top: 4px;\n  font-size: 18px;\n}\n\n.status {\n  min-height: 28px;\n  margin: 14px 0 0;\n  font-weight: 800;\n}\n\n.status.ok {\n  color: var(--green);\n}\n\n.status.error {\n  color: var(--red);\n}\n\n.admin-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 16px;\n  margin-bottom: 18px;\n}\n\n.admin-link-card {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  margin: 0 0 18px;\n  padding: 16px;\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  background: #fbfdff;\n}\n\n.admin-link-card h3 {\n  margin: 0 0 6px;\n}\n\n.admin-link-card p {\n  margin: 0;\n  color: var(--muted);\n}\n\n.admin-link-buttons {\n  display: flex;\n  gap: 10px;\n  flex-wrap: wrap;\n}\n\n.admin-link-buttons a {\n  display: inline-grid;\n  place-items: center;\n  min-height: 44px;\n  padding: 10px 14px;\n  border: 1px solid var(--blue);\n  border-radius: 8px;\n  color: var(--blue);\n  background: #fff;\n  font-weight: 800;\n  text-decoration: none;\n}\n\n.admin-card {\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  padding: 16px;\n  background: #fbfdff;\n}\n\n.admin-card h3 {\n  margin: 0 0 12px;\n}\n\n.master-form {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 120px 90px;\n  gap: 8px;\n  margin-bottom: 12px;\n}\n\n#teacherMasterForm {\n  grid-template-columns: minmax(0, 1fr) 90px;\n}\n\n.master-list {\n  display: grid;\n  gap: 8px;\n  max-height: 220px;\n  overflow: auto;\n  padding: 8px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #f6f9fd;\n}\n\n.master-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 10px 12px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #fff;\n}\n\n.master-row small {\n  color: var(--muted);\n  font-weight: 700;\n}\n\n.master-row button {\n  min-height: 34px;\n  padding: 5px 10px;\n  color: var(--red);\n}\n\n.admin-actions {\n  display: flex;\n  gap: 10px;\n  flex-wrap: wrap;\n  margin: 20px 0 14px;\n}\n\n.results-summary {\n  display: flex;\n  gap: 10px;\n  flex-wrap: wrap;\n  margin-bottom: 14px;\n}\n\n.results-summary span {\n  padding: 8px 12px;\n  border-radius: 999px;\n  background: var(--blue-soft);\n  font-weight: 800;\n}\n\n.results-area {\n  display: grid;\n  gap: 20px;\n}\n\n.result-table-wrap {\n  max-width: 100%;\n  overflow-x: auto;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n}\n\n.result-table,\n.matrix-table {\n  width: 100%;\n  border-collapse: collapse;\n  table-layout: fixed;\n  min-width: 0;\n}\n\n.matrix-table {\n  font-size: 13px;\n}\n\n.student-matrix {\n  min-width: 1040px;\n}\n\n.teacher-matrix {\n  min-width: 780px;\n}\n\n.result-table th,\n.result-table td,\n.matrix-table th,\n.matrix-table td {\n  border-bottom: 1px solid var(--line);\n  border-right: 1px solid var(--line);\n  padding: 8px 6px;\n  text-align: left;\n  vertical-align: middle;\n  overflow-wrap: anywhere;\n  word-break: keep-all;\n}\n\n.result-table th,\n.matrix-table th {\n  background: #f6f9fd;\n  font-weight: 800;\n}\n\n.matrix-table th {\n  line-height: 1.35;\n  text-align: center;\n}\n\n.student-matrix th:first-child,\n.student-matrix td:first-child {\n  width: 82px;\n}\n\n.student-matrix th:nth-child(2),\n.student-matrix td:nth-child(2) {\n  width: 70px;\n}\n\n.student-matrix th:nth-child(3),\n.student-matrix td:nth-child(3) {\n  width: 50px;\n}\n\n.student-matrix th:last-child,\n.student-matrix td:last-child {\n  width: 58px;\n  text-align: center;\n}\n\n.student-matrix th:nth-last-child(2),\n.student-matrix td:nth-last-child(2) {\n  width: 70px;\n}\n\n.teacher-matrix th:first-child,\n.teacher-matrix td:first-child {\n  width: 82px;\n}\n\n.teacher-matrix th:nth-child(2),\n.teacher-matrix td:nth-child(2) {\n  width: 120px;\n}\n\n.teacher-matrix th:last-child,\n.teacher-matrix td:last-child {\n  width: 58px;\n  text-align: center;\n}\n\n.teacher-matrix th:nth-last-child(2),\n.teacher-matrix td:nth-last-child(2) {\n  width: 90px;\n}\n\n.matrix-table .mark {\n  text-align: center;\n  font-size: 22px;\n  font-weight: 900;\n  color: var(--green);\n}\n\n.matrix-action {\n  text-align: center;\n}\n\n.result-table th:first-child,\n.result-table td:first-child {\n  width: 96px;\n}\n\n.result-table th:nth-child(2),\n.result-table td:nth-child(2),\n.result-table th:nth-child(3),\n.result-table td:nth-child(3) {\n  width: 72px;\n}\n\n.result-table th:last-child,\n.result-table td:last-child {\n  width: 72px;\n  text-align: center;\n}\n\n.danger-small {\n  min-height: 34px;\n  padding: 5px 10px;\n  border-color: #fecaca;\n  color: var(--red);\n  background: #fff7f7;\n}\n\n.empty {\n  margin: 0;\n  color: var(--muted);\n}\n\n@media (max-width: 760px) {\n  .app {\n    width: 100%;\n    padding: 10px 8px 28px;\n  }\n\n  .hero {\n    padding: 16px 4px 12px;\n  }\n\n  .hero h1 {\n    font-size: 30px;\n  }\n\n  .hero span {\n    font-size: 16px;\n  }\n\n  .panel {\n    padding: 14px 12px;\n    border-radius: 8px;\n  }\n\n  .panel-title h2 {\n    font-size: 28px;\n  }\n\n  .panel-title p {\n    font-size: 16px;\n    line-height: 1.7;\n  }\n\n  .tabs {\n    gap: 6px;\n    padding: 6px 0;\n  }\n\n  .tab {\n    min-width: 0;\n    min-height: 46px;\n    padding: 9px 6px;\n    font-size: 15px;\n  }\n\n  .slot-grid {\n    grid-template-columns: 72px repeat(5, minmax(0, 1fr));\n  }\n\n  .slot-grid > div,\n  .slot-grid .slot {\n    min-height: 56px;\n    padding: 6px 3px;\n    font-size: 14px;\n  }\n\n  .slot-grid .head {\n    font-size: 14px;\n  }\n\n  .slot-grid .time {\n    font-size: 13px;\n    line-height: 1.25;\n  }\n\n  .teacher-days {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .teacher-days button:nth-child(2n + 1) {\n    border-left: 0;\n  }\n\n  .teacher-days button {\n    min-height: 64px;\n    padding: 10px 6px;\n  }\n\n  .admin-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .admin-link-card {\n    align-items: stretch;\n    flex-direction: column;\n  }\n\n  .admin-link-buttons a {\n    flex: 1 1 160px;\n  }\n\n  .master-form,\n  #teacherMasterForm {\n    grid-template-columns: 1fr;\n  }\n\n  .student-select-row {\n    grid-template-columns: 1fr;\n  }\n\n  .result-table-wrap {\n    overflow-x: auto;\n  }\n}\n\n@media (max-width: 420px) {\n  .app {\n    padding-left: 6px;\n    padding-right: 6px;\n  }\n\n  .panel {\n    padding-left: 10px;\n    padding-right: 10px;\n  }\n\n  .slot-grid {\n    grid-template-columns: 66px repeat(5, minmax(0, 1fr));\n  }\n\n  .slot-grid > div,\n  .slot-grid .slot {\n    min-height: 54px;\n    font-size: 13px;\n  }\n\n  .slot-grid .time {\n    font-size: 12px;\n  }\n}\n","type":"text/css; charset=utf-8"},"/app.js":{"body":"const SUPABASE = {\n  url: \"https://dlymqxjxandoxponairu.supabase.co\",\n  key: \"sb_publishable_EJKOxEgtTCaQdzlcTpffAw_68oyJFQ9\",\n  submissionsTable: \"september_survey_submissions\",\n  peopleTable: \"september_survey_people\",\n};\n\nconst weekdays = [\n  { id: \"mon\", label: \"月曜日\" },\n  { id: \"tue\", label: \"火曜日\" },\n  { id: \"wed\", label: \"水曜日\" },\n  { id: \"thu\", label: \"木曜日\" },\n  { id: \"fri\", label: \"金曜日\" },\n];\n\nconst teacherDays = [\n  { id: \"mon\", label: \"月曜日\", time: \"19:00-22:00\" },\n  { id: \"tue\", label: \"火曜日\", time: \"19:00-22:00\" },\n  { id: \"wed\", label: \"水曜日\", time: \"19:00-22:00\" },\n  { id: \"thu\", label: \"木曜日\", time: \"19:00-22:00\" },\n  { id: \"fri\", label: \"金曜日\", time: \"19:00-22:00\" },\n  { id: \"sat\", label: \"土曜日\", time: \"17:00-22:00\" },\n];\n\nconst studentSlots = [\n  { id: \"19\", label: \"19:00-19:50\" },\n  { id: \"20\", label: \"20:00-20:50\" },\n  { id: \"21\", label: \"21:00-21:50\" },\n];\n\nconst localSubmissionPrefix = \"septemberSurveySubmission\";\nconst gradeOrder = [\"小4\", \"小5\", \"小6\", \"中1\", \"中2\", \"中3\", \"高1\", \"高2\", \"高3\"];\n\nconst pageLabels = {\n  student: \"生徒用\",\n  teacher: \"講師用\",\n  admin: \"管理用\",\n};\n\nconst pageLeads = {\n  student: \"最初はすべて〇にしています。来られない日時だけタップして×にしてから提出してください。\",\n  teacher: \"9月からの勤務日時を決めるため、来れる日時をタップして提出をお願いします。期限は8/16（日）までです。もし期限内の提出が厳しければお知らせください。\",\n  admin: \"生徒・講師の名前を登録し、回答結果を確認します。\",\n};\n\nconst state = {\n  page: new URLSearchParams(location.search).get(\"page\") || \"admin\",\n  student: new Set(),\n  teacher: new Set(),\n  people: [],\n  results: [],\n};\n\nconst elements = {\n  pageLead: document.querySelector(\"#pageLead\"),\n  tabs: [...document.querySelectorAll(\".tab\")],\n  views: [...document.querySelectorAll(\".view\")],\n  status: document.querySelector(\"#statusMessage\"),\n  studentForm: document.querySelector(\"#studentForm\"),\n  teacherForm: document.querySelector(\"#teacherForm\"),\n  studentName: document.querySelector(\"#studentName\"),\n  studentGrade: document.querySelector(\"#studentGrade\"),\n  teacherName: document.querySelector(\"#teacherName\"),\n  studentGrid: document.querySelector(\"#studentGrid\"),\n  teacherGrid: document.querySelector(\"#teacherGrid\"),\n  studentReview: document.querySelector(\"#studentReview\"),\n  teacherReview: document.querySelector(\"#teacherReview\"),\n  studentMasterForm: document.querySelector(\"#studentMasterForm\"),\n  teacherMasterForm: document.querySelector(\"#teacherMasterForm\"),\n  studentMasterName: document.querySelector(\"#studentMasterName\"),\n  studentMasterGrade: document.querySelector(\"#studentMasterGrade\"),\n  teacherMasterName: document.querySelector(\"#teacherMasterName\"),\n  studentMasterList: document.querySelector(\"#studentMasterList\"),\n  teacherMasterList: document.querySelector(\"#teacherMasterList\"),\n  loadResultsButton: document.querySelector(\"#loadResultsButton\"),\n  downloadCsvButton: document.querySelector(\"#downloadCsvButton\"),\n  resultsArea: document.querySelector(\"#resultsArea\"),\n  studentCount: document.querySelector(\"#studentCount\"),\n  teacherCount: document.querySelector(\"#teacherCount\"),\n};\n\nfunction apiUrl(table, query = \"\") {\n  return `${SUPABASE.url}/rest/v1/${table}${query}`;\n}\n\nfunction apiHeaders(extra = {}) {\n  return {\n    apikey: SUPABASE.key,\n    Authorization: `Bearer ${SUPABASE.key}`,\n    \"Content-Type\": \"application/json\",\n    ...extra,\n  };\n}\n\nfunction showStatus(message, type = \"ok\") {\n  elements.status.textContent = message;\n  elements.status.className = `status ${type}`;\n}\n\nfunction showPage(page) {\n  state.page = pageLabels[page] ? page : \"admin\";\n  document.body.dataset.page = state.page;\n  elements.views.forEach((panel) => panel.classList.toggle(\"active\", panel.id === `${state.page}View`));\n  elements.tabs.forEach((tab) => tab.classList.toggle(\"active\", tab.dataset.pageLink === state.page));\n  elements.pageLead.textContent = pageLeads[state.page];\n  showStatus(\"\");\n}\n\nfunction renderStudentGrid() {\n  const cells = [\n    '<div class=\"head\">時間</div>',\n    ...weekdays.map((day) => `<div class=\"head\">${day.label.replace(\"曜日\", \"\")}</div>`),\n  ];\n\n  for (const slot of studentSlots) {\n    cells.push(`<div class=\"time\">${slot.label}</div>`);\n    for (const day of weekdays) {\n      const key = `${day.id}_${slot.id}`;\n      const available = state.student.has(key);\n      cells.push(`<button class=\"slot ${available ? \"selected\" : \"unavailable\"}\" type=\"button\" data-student-slot=\"${key}\">${available ? \"〇\" : \"×\"}</button>`);\n    }\n  }\n\n  elements.studentGrid.innerHTML = cells.join(\"\");\n}\n\nfunction allStudentSlotKeys() {\n  return weekdays.flatMap((day) => studentSlots.map((slot) => `${day.id}_${slot.id}`));\n}\n\nfunction selectAllStudentSlots() {\n  state.student = new Set(allStudentSlotKeys());\n}\n\nfunction renderTeacherGrid() {\n  elements.teacherGrid.innerHTML = teacherDays.map((day) => `\n    <button class=\"${state.teacher.has(day.id) ? \"selected\" : \"\"}\" type=\"button\" data-teacher-day=\"${day.id}\">\n      <span>${day.label}</span>\n      <small>${day.time}</small>\n      <strong>${state.teacher.has(day.id) ? \"〇\" : \"\"}</strong>\n    </button>\n  `).join(\"\");\n}\n\nfunction gradeRank(grade) {\n  const index = gradeOrder.indexOf(grade);\n  return index === -1 ? 999 : index;\n}\n\nfunction sortStudents(students) {\n  return [...students].sort((a, b) =>\n    gradeRank(a.grade) - gradeRank(b.grade)\n    || String(a.name ?? a.respondent_name).localeCompare(String(b.name ?? b.respondent_name), \"ja\")\n  );\n}\n\nfunction sortTeachers(teachers) {\n  return [...teachers].sort((a, b) =>\n    String(a.name ?? a.respondent_name).localeCompare(String(b.name ?? b.respondent_name), \"ja\")\n  );\n}\n\nfunction renderStudentNameOptions(students = sortStudents(state.people.filter((person) => person.role === \"student\"))) {\n  const grade = elements.studentGrade.value;\n  const filtered = grade ? students.filter((person) => person.grade === grade) : [];\n  elements.studentName.disabled = !grade;\n  elements.studentName.innerHTML = !grade\n    ? '<option value=\"\">未選択</option>'\n    : '<option value=\"\">未選択</option>' + filtered.map((person) =>\n      `<option value=\"${escapeHtml(person.name)}\">${escapeHtml(person.name)}</option>`\n    ).join(\"\");\n}\n\nfunction sortBySubmittedAt(rows) {\n  return [...rows].sort((a, b) => {\n    const dateDiff = new Date(b.created_at).getTime() - new Date(a.created_at).getTime();\n    if (dateDiff) return dateDiff;\n    return Number(b.id ?? 0) - Number(a.id ?? 0);\n  });\n}\n\nfunction renderPeople() {\n  const students = sortStudents(state.people.filter((person) => person.role === \"student\"));\n  const teachers = sortTeachers(state.people.filter((person) => person.role === \"teacher\"));\n  const selectedGrade = elements.studentGrade.value;\n  const availableGrades = [...new Set(students.map((person) => person.grade).filter(Boolean))]\n    .sort((a, b) => gradeRank(a) - gradeRank(b));\n\n  elements.studentGrade.innerHTML = '<option value=\"\">未選択</option>' + availableGrades.map((grade) =>\n    `<option value=\"${escapeHtml(grade)}\">${escapeHtml(grade)}</option>`\n  ).join(\"\");\n  if (availableGrades.includes(selectedGrade)) elements.studentGrade.value = selectedGrade;\n  else elements.studentGrade.value = \"\";\n  renderStudentNameOptions(students);\n\n  elements.teacherName.innerHTML = '<option value=\"\">未選択</option>' + teachers.map((person) =>\n    `<option value=\"${escapeHtml(person.name)}\">${escapeHtml(person.name)}</option>`\n  ).join(\"\");\n\n  elements.studentMasterList.innerHTML = renderMasterList(students, true);\n  elements.teacherMasterList.innerHTML = renderMasterList(teachers, false);\n}\n\nfunction renderMasterList(people, showGrade) {\n  if (!people.length) return '<p class=\"empty\">まだ登録がありません。</p>';\n  return people.map((person) => `\n    <div class=\"master-row\">\n      <span>${escapeHtml(person.name)}${showGrade ? ` <small>${escapeHtml(person.grade ?? \"\")}</small>` : \"\"}</span>\n      <button type=\"button\" data-delete-person=\"${person.id}\">削除</button>\n    </div>\n  `).join(\"\");\n}\n\nasync function fetchPeople() {\n  const response = await fetch(apiUrl(SUPABASE.peopleTable, \"?select=*&active=eq.true&order=role.asc,name.asc\"), {\n    headers: apiHeaders(),\n  });\n  if (!response.ok) throw new Error(await response.text() || \"名簿の読み込みに失敗しました。\");\n  state.people = await response.json();\n  renderPeople();\n}\n\nasync function addPerson(role, name, grade = null) {\n  const response = await fetch(apiUrl(SUPABASE.peopleTable, \"?on_conflict=role,name\"), {\n    method: \"POST\",\n    headers: apiHeaders({ Prefer: \"resolution=merge-duplicates,return=minimal\" }),\n    body: JSON.stringify({ role, name, grade, active: true }),\n  });\n  if (!response.ok) throw new Error(await response.text() || \"名前の追加に失敗しました。\");\n}\n\nasync function deletePerson(id) {\n  const response = await fetch(apiUrl(SUPABASE.peopleTable, `?id=eq.${encodeURIComponent(id)}`), {\n    method: \"PATCH\",\n    headers: apiHeaders({ Prefer: \"return=minimal\" }),\n    body: JSON.stringify({ active: false }),\n  });\n  if (!response.ok) throw new Error(await response.text() || \"削除に失敗しました。\");\n}\n\nfunction buildStudentAvailability() {\n  return weekdays.map((day) => ({\n    day: day.id,\n    label: day.label,\n    slots: studentSlots.map((slot) => ({\n      slot: slot.id,\n      time: slot.label,\n      available: state.student.has(`${day.id}_${slot.id}`),\n    })),\n  }));\n}\n\nfunction buildTeacherAvailability() {\n  return teacherDays.map((day) => ({\n    day: day.id,\n    label: day.label,\n    time: day.time,\n    available: state.teacher.has(day.id),\n  }));\n}\n\nasync function insertSubmission(payload) {\n  const submission = { ...payload, created_at: new Date().toISOString() };\n  const response = await fetch(apiUrl(SUPABASE.submissionsTable, \"?on_conflict=role,respondent_name\"), {\n    method: \"POST\",\n    headers: apiHeaders({ Prefer: \"resolution=merge-duplicates,return=representation\" }),\n    body: JSON.stringify(submission),\n  });\n  if (!response.ok) throw new Error(await response.text() || \"送信に失敗しました。\");\n  const saved = await response.json();\n  return saved[0] ?? submission;\n}\n\nasync function fetchResults() {\n  const response = await fetch(apiUrl(SUPABASE.submissionsTable, \"?select=*&order=created_at.desc\"), {\n    headers: apiHeaders(),\n  });\n  if (!response.ok) throw new Error(await response.text() || \"読み込みに失敗しました。\");\n  return response.json();\n}\n\nasync function deleteSubmission(id) {\n  const response = await fetch(apiUrl(SUPABASE.submissionsTable, `?id=eq.${encodeURIComponent(id)}`), {\n    method: \"DELETE\",\n    headers: apiHeaders({ Prefer: \"return=minimal\" }),\n  });\n  if (!response.ok) throw new Error(await response.text() || \"回答の削除に失敗しました。\");\n}\n\nfunction matrixSlotLabel(day, slot) {\n  return `\n    <span>${day.label.replace(\"曜日\", \"\")}</span>\n    <span>${slot.label.replace(\"-\", \"<br>\")}</span>\n  `;\n}\n\nfunction renderResults() {\n  const students = sortBySubmittedAt(state.results.filter((row) => row.role === \"student\"));\n  const teachers = sortBySubmittedAt(state.results.filter((row) => row.role === \"teacher\"));\n  elements.studentCount.textContent = `生徒 ${students.length}件`;\n  elements.teacherCount.textContent = `講師 ${teachers.length}件`;\n\n  if (!state.results.length) {\n    elements.resultsArea.innerHTML = '<p class=\"empty\">回答はまだありません。</p>';\n    return;\n  }\n\n  elements.resultsArea.innerHTML = `\n    ${renderStudentMatrix(students)}\n    ${renderTeacherMatrix(teachers)}\n  `;\n}\n\nfunction renderStudentMatrix(rows) {\n  if (!rows.length) return \"\";\n  return `\n    <section>\n      <h3>生徒 通塾可能表</h3>\n      <div class=\"result-table-wrap\">\n        <table class=\"matrix-table student-matrix\">\n          <thead>\n            <tr>\n              <th>回答日時</th>\n              <th>名前</th>\n              <th>学年</th>\n              ${weekdays.flatMap((day) => studentSlots.map((slot) => `<th>${matrixSlotLabel(day, slot)}</th>`)).join(\"\")}\n              <th>補足</th>\n              <th>操作</th>\n            </tr>\n          </thead>\n          <tbody>\n            ${rows.map((row) => `\n              <tr>\n                <td>${formatDate(row.created_at)}</td>\n                <td>${escapeHtml(row.respondent_name)}</td>\n                <td>${escapeHtml(row.grade ?? \"\")}</td>\n                ${weekdays.flatMap((day) => studentSlots.map((slot) => `<td class=\"mark\">${hasStudentSlot(row, day.id, slot.id) ? \"〇\" : \"\"}</td>`)).join(\"\")}\n                <td>${escapeHtml(row.memo ?? \"\")}</td>\n                <td class=\"matrix-action\">${deleteSubmissionButton(row.id)}</td>\n              </tr>\n            `).join(\"\")}\n          </tbody>\n        </table>\n      </div>\n    </section>\n  `;\n}\n\nfunction renderTeacherMatrix(rows) {\n  if (!rows.length) return \"\";\n  return `\n    <section>\n      <h3>講師 勤務可能表</h3>\n      <div class=\"result-table-wrap\">\n        <table class=\"matrix-table teacher-matrix\">\n          <thead>\n            <tr>\n              <th>回答日時</th>\n              <th>名前</th>\n              ${teacherDays.map((day) => `<th>${day.label}<br>${day.time}</th>`).join(\"\")}\n              <th>補足</th>\n              <th>操作</th>\n            </tr>\n          </thead>\n          <tbody>\n            ${rows.map((row) => `\n              <tr>\n                <td>${formatDate(row.created_at)}</td>\n                <td>${escapeHtml(row.respondent_name)}</td>\n                ${teacherDays.map((day) => `<td class=\"mark\">${hasTeacherDay(row, day.id) ? \"〇\" : \"\"}</td>`).join(\"\")}\n                <td>${escapeHtml(row.memo ?? \"\")}</td>\n                <td class=\"matrix-action\">${deleteSubmissionButton(row.id)}</td>\n              </tr>\n            `).join(\"\")}\n          </tbody>\n        </table>\n      </div>\n    </section>\n  `;\n}\n\nfunction deleteSubmissionButton(id) {\n  return `<button class=\"danger-small\" type=\"button\" data-delete-submission=\"${escapeHtml(id)}\">削除</button>`;\n}\n\nfunction hasStudentSlot(row, dayId, slotId) {\n  const day = (row.availability ?? []).find((item) => item.day === dayId);\n  return Boolean(day?.slots?.some((slot) => slot.slot === slotId && slot.available));\n}\n\nfunction hasTeacherDay(row, dayId) {\n  return Boolean((row.availability ?? []).find((day) => day.day === dayId && day.available));\n}\n\nfunction formatAvailability(row) {\n  const availability = row.availability ?? [];\n  if (row.role === \"teacher\") {\n    return availability.filter((day) => day.available).map((day) => `${day.label} ${day.time}`).join(\" / \");\n  }\n  return availability.map((day) => {\n    const slots = day.slots.filter((slot) => slot.available).map((slot) => slot.time);\n    return slots.length ? `${day.label}: ${slots.join(\", \")}` : \"\";\n  }).filter(Boolean).join(\" / \");\n}\n\nfunction formatDate(value) {\n  if (!value) return \"\";\n  const date = new Date(value);\n  if (Number.isNaN(date.getTime())) return \"\";\n  return new Intl.DateTimeFormat(\"ja-JP\", {\n    timeZone: \"Asia/Tokyo\",\n    month: \"2-digit\",\n    day: \"2-digit\",\n    hour: \"2-digit\",\n    minute: \"2-digit\",\n    hour12: false,\n  }).format(date);\n}\n\nfunction localSubmissionKey(role, name) {\n  return `${localSubmissionPrefix}:${role}:${name}`;\n}\n\nfunction saveLocalSubmission(submission) {\n  try {\n    localStorage.setItem(localSubmissionKey(submission.role, submission.respondent_name), JSON.stringify(submission));\n  } catch {\n    // Local answer review is a convenience; submission itself has already succeeded.\n  }\n}\n\nfunction readLocalSubmission(role, name) {\n  if (!name) return null;\n  try {\n    const value = localStorage.getItem(localSubmissionKey(role, name));\n    return value ? JSON.parse(value) : null;\n  } catch {\n    return null;\n  }\n}\n\nfunction renderOwnAnswer(role, submission) {\n  const element = role === \"student\" ? elements.studentReview : elements.teacherReview;\n  if (!element) return;\n  if (!submission) {\n    element.innerHTML = \"\";\n    return;\n  }\n  element.innerHTML = `\n    <div class=\"own-answer-title\">前回送信した内容</div>\n    <table>\n      <tbody>\n        <tr>\n          <th>回答日時</th>\n          <td>${formatDate(submission.created_at)}</td>\n        </tr>\n        <tr>\n          <th>可能日時</th>\n          <td>${escapeHtml(formatAvailability(submission) || \"なし\")}</td>\n        </tr>\n        <tr>\n          <th>補足</th>\n          <td>${escapeHtml(submission.memo ?? \"\")}</td>\n        </tr>\n      </tbody>\n    </table>\n  `;\n}\n\nfunction applyStudentSubmission(submission) {\n  state.student = new Set(\n    (submission.availability ?? []).flatMap((day) =>\n      (day.slots ?? [])\n        .filter((slot) => slot.available)\n        .map((slot) => `${day.day}_${slot.slot}`)\n    )\n  );\n  document.querySelector(\"#studentMemo\").value = submission.memo ?? \"\";\n  renderStudentGrid();\n}\n\nfunction applyTeacherSubmission(submission) {\n  state.teacher = new Set(\n    (submission.availability ?? [])\n      .filter((day) => day.available)\n      .map((day) => day.day)\n  );\n  document.querySelector(\"#teacherMemo\").value = submission.memo ?? \"\";\n  renderTeacherGrid();\n}\n\nfunction loadOwnStudentAnswer() {\n  const submission = readLocalSubmission(\"student\", elements.studentName.value);\n  if (submission) {\n    applyStudentSubmission(submission);\n  } else {\n    selectAllStudentSlots();\n    document.querySelector(\"#studentMemo\").value = \"\";\n    renderStudentGrid();\n  }\n  renderOwnAnswer(\"student\", submission);\n}\n\nfunction loadOwnTeacherAnswer() {\n  const submission = readLocalSubmission(\"teacher\", elements.teacherName.value);\n  if (submission) applyTeacherSubmission(submission);\n  renderOwnAnswer(\"teacher\", submission);\n}\n\nfunction escapeHtml(value) {\n  return String(value ?? \"\")\n    .replaceAll(\"&\", \"&amp;\")\n    .replaceAll(\"<\", \"&lt;\")\n    .replaceAll(\">\", \"&gt;\")\n    .replaceAll('\"', \"&quot;\")\n    .replaceAll(\"'\", \"&#039;\");\n}\n\nfunction makeCsv() {\n  const headers = [\"種別\", \"回答日時\", \"名前\", \"学年\", \"可能日時\", \"補足\"];\n  const rows = state.results.map((row) => [\n    row.role === \"student\" ? \"生徒\" : \"講師\",\n    row.created_at ?? \"\",\n    row.respondent_name ?? \"\",\n    row.grade ?? \"\",\n    formatAvailability(row),\n    row.memo ?? \"\",\n  ]);\n  return [headers, ...rows].map((row) => row.map(csvCell).join(\",\")).join(\"\\r\\n\");\n}\n\nfunction csvCell(value) {\n  return `\"${String(value ?? \"\").replaceAll('\"', '\"\"')}\"`;\n}\n\nfunction downloadCsv() {\n  if (!state.results.length) {\n    showStatus(\"先に結果を読み込んでください。\", \"error\");\n    return;\n  }\n  const blob = new Blob([`\\uFEFF${makeCsv()}`], { type: \"text/csv;charset=utf-8\" });\n  const url = URL.createObjectURL(blob);\n  const link = document.createElement(\"a\");\n  link.href = url;\n  link.download = \"9月通常授業アンケート結果.csv\";\n  link.click();\n  URL.revokeObjectURL(url);\n}\n\nelements.studentGrade.addEventListener(\"change\", () => {\n  renderStudentNameOptions();\n  selectAllStudentSlots();\n  renderStudentGrid();\n  renderOwnAnswer(\"student\", null);\n});\n\nelements.studentName.addEventListener(\"change\", loadOwnStudentAnswer);\nelements.teacherName.addEventListener(\"change\", loadOwnTeacherAnswer);\n\nelements.studentGrid.addEventListener(\"click\", (event) => {\n  const key = event.target.dataset.studentSlot;\n  if (!key) return;\n  if (state.student.has(key)) state.student.delete(key);\n  else state.student.add(key);\n  renderStudentGrid();\n});\n\nelements.teacherGrid.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"[data-teacher-day]\");\n  if (!button) return;\n  const key = button.dataset.teacherDay;\n  if (state.teacher.has(key)) state.teacher.delete(key);\n  else state.teacher.add(key);\n  renderTeacherGrid();\n});\n\nelements.studentForm.addEventListener(\"submit\", async (event) => {\n  event.preventDefault();\n  const name = elements.studentName.value;\n  const grade = elements.studentGrade.value;\n  const memo = document.querySelector(\"#studentMemo\").value.trim();\n  if (!state.student.size) {\n    showStatus(\"通塾できる日時を1つ以上〇のまま残してください。\", \"error\");\n    return;\n  }\n  showStatus(\"送信中です...\");\n  try {\n    const submission = await insertSubmission({ role: \"student\", respondent_name: name, grade, availability: buildStudentAvailability(), memo });\n    saveLocalSubmission(submission);\n    elements.studentForm.reset();\n    renderStudentNameOptions();\n    selectAllStudentSlots();\n    renderStudentGrid();\n    renderOwnAnswer(\"student\", submission);\n    showStatus(\"送信しました。前回の回答がある場合は上書きしました。\");\n  } catch (error) {\n    showStatus(`送信できませんでした。${error.message}`, \"error\");\n  }\n});\n\nelements.teacherForm.addEventListener(\"submit\", async (event) => {\n  event.preventDefault();\n  const name = elements.teacherName.value;\n  const memo = document.querySelector(\"#teacherMemo\").value.trim();\n  if (!state.teacher.size) {\n    showStatus(\"勤務できる曜日を1つ以上選択してください。\", \"error\");\n    return;\n  }\n  showStatus(\"送信中です...\");\n  try {\n    const submission = await insertSubmission({ role: \"teacher\", respondent_name: name, grade: null, availability: buildTeacherAvailability(), memo });\n    saveLocalSubmission(submission);\n    elements.teacherForm.reset();\n    state.teacher.clear();\n    renderTeacherGrid();\n    renderOwnAnswer(\"teacher\", submission);\n    showStatus(\"送信しました。前回の回答がある場合は上書きしました。\");\n  } catch (error) {\n    showStatus(`送信できませんでした。${error.message}`, \"error\");\n  }\n});\n\nelements.studentMasterForm.addEventListener(\"submit\", async (event) => {\n  event.preventDefault();\n  const name = elements.studentMasterName.value.trim();\n  const grade = elements.studentMasterGrade.value;\n  if (!name || !grade) {\n    showStatus(\"生徒名と学年を入力してください。\", \"error\");\n    return;\n  }\n  try {\n    await addPerson(\"student\", name, grade);\n    elements.studentMasterForm.reset();\n    await fetchPeople();\n    showStatus(\"生徒名を追加しました。\");\n  } catch (error) {\n    showStatus(`追加できませんでした。${error.message}`, \"error\");\n  }\n});\n\nelements.teacherMasterForm.addEventListener(\"submit\", async (event) => {\n  event.preventDefault();\n  const name = elements.teacherMasterName.value.trim();\n  if (!name) {\n    showStatus(\"講師名を入力してください。\", \"error\");\n    return;\n  }\n  try {\n    await addPerson(\"teacher\", name);\n    elements.teacherMasterForm.reset();\n    await fetchPeople();\n    showStatus(\"講師名を追加しました。\");\n  } catch (error) {\n    showStatus(`追加できませんでした。${error.message}`, \"error\");\n  }\n});\n\ndocument.addEventListener(\"click\", async (event) => {\n  const deletePersonButton = event.target.closest(\"[data-delete-person]\");\n  const personId = deletePersonButton?.dataset.deletePerson;\n  if (personId) {\n    try {\n      await deletePerson(personId);\n      await fetchPeople();\n      showStatus(\"名簿から外しました。\");\n    } catch (error) {\n      showStatus(`削除できませんでした。${error.message}`, \"error\");\n    }\n    return;\n  }\n\n  const deleteSubmissionTarget = event.target.closest(\"[data-delete-submission]\");\n  const submissionId = deleteSubmissionTarget?.dataset.deleteSubmission;\n  if (!submissionId) return;\n  if (!confirm(\"この回答を削除しますか？\")) return;\n  try {\n    await deleteSubmission(submissionId);\n    state.results = await fetchResults();\n    renderResults();\n    showStatus(\"回答を削除しました。\");\n  } catch (error) {\n    showStatus(`削除できませんでした。${error.message}`, \"error\");\n  }\n});\n\nelements.loadResultsButton.addEventListener(\"click\", async () => {\n  await loadResults();\n});\n\nasync function loadResults({ silent = false } = {}) {\n  if (!silent) {\n    showStatus(\"結果を読み込んでいます...\");\n  }\n  elements.loadResultsButton.disabled = true;\n  try {\n    state.results = await fetchResults();\n    renderResults();\n    showStatus(\"結果を読み込みました。\");\n  } catch (error) {\n    showStatus(`読み込めませんでした。${error.message}`, \"error\");\n  } finally {\n    elements.loadResultsButton.disabled = false;\n  }\n}\n\nelements.downloadCsvButton.addEventListener(\"click\", downloadCsv);\n\nif (state.page === \"student\") selectAllStudentSlots();\nrenderStudentGrid();\nrenderTeacherGrid();\nshowPage(state.page);\nfetchPeople().catch((error) => showStatus(`名簿を読み込めませんでした。${error.message}`, \"error\"));\nif (state.page === \"admin\") {\n  loadResults({ silent: true });\n}\n","type":"application/javascript; charset=utf-8"}};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const path = url.pathname === "/" ? "/index.html" : url.pathname;
    const asset = ASSETS[path] || ASSETS["/index.html"];
    return new Response(asset.body, {
      headers: {
        "content-type": asset.type,
        "cache-control": "no-store",
      },
    });
  },
};
